pages={
'uk':('United Kingdom','An economy of connected possibilities.','Explore the industries, enterprises and public institutions shaping the UK.','uk-economy.webp',[('£2.62tn','UK GVA · 2024 · current basic prices'),('100%','Whole-economy reference · UK GVA'),('+0.7%','Real GDP · 3 months to Sep 2026 vs previous 3 months')],[('banking','Banking','Finance, trust & everyday commerce'),('technology','Technology','Compute, connectivity & transformation'),('government','Government','Public services & national priorities')]),
'banking':('UK Banking','Where capital meets the real economy.','Understand the institutions, infrastructure and pressures shaping financial services.','uk-economy.webp',[('8.1%','Finance & insurance · share of UK GVA · 2024'),('—','Banking-only GVA · not established'),('—','Comparable real Banking growth · unavailable')],[('lloyds','Lloyds Banking Group','Enterprise portrait'),('landscape','Banks & building societies','Grouped enterprise landscape'),('ecosystem','Infrastructure & oversight','Suppliers and regulators · context')]),
 'technology':('UK Technology','The infrastructure of what comes next.','Move from the technology landscape to the enterprises behind it.','uk-technology.webp',[('6.6%','Information & communication · UK GVA share · 2024'),('—','Technology-only GVA · not established'),('—','Comparable real Technology growth · unavailable')],[('nvidia','NVIDIA','Enterprise portrait · global group'),('landscape','Cloud, software & connectivity','Grouped enterprise landscape'),('ecosystem','Supply chain & oversight','Actor roles · no assumed relationships')]),
 'lloyds':('Lloyds Banking Group','A closer view of the customer.','Understand the business before deciding where a useful conversation begins.','uk-economy.webp',[('—','Group income · retain banking accounting basis'),('—','Comparable growth · source review required'),('UK focus','Group footprint · not a UK GVA share')],[('operating','Businesses & operations','Illustrative grouping · not an organisation chart'),('ecosystem','Customers, suppliers & oversight','Relationship evidence required'),('questions','Commercial questions','Need, access and scope remain unconfirmed')]),
'nvidia':('NVIDIA','Inside the accelerated-computing economy.','Explore the enterprise, its operating context and the questions worth investigating.','uk-technology.webp',[('$215.94bn','Global group revenue · USD · FY2026 · ended 25 Jan 2026'),('—','Reported revenue growth · period/basis required'),('Global','Group boundary · UK sales not disclosed here')],[('operating','Platforms & operating model','Conceptual · validate against enterprise evidence'),('ecosystem','Customers, supply chain & oversight','Named edges only when sourced'),('questions','Commercial questions','Public strategy is not customer demand')]),
'government':('UK Government','A different lens on the same country.','Public services, national priorities and accountable spending.','uk-economy.webp',[('5.1%','Public administration & defence · UK GVA share · 2024'),('—','Public spending · fiscal-year source required'),('—','Receipts / borrowing · separate fiscal measures')],[('services','Departments & public services','Illustrative navigation concept'),('procurement','Procurement & programmes','No live procurement asserted'),('ecosystem','Regulators & delivery ecosystem','Role and jurisdiction required')])}
# All detailed targets are static design disclosures, never product routes.
for alt,name in [('a','Continuous Panorama'),('b','Spatial Atlas'),('c','Editorial Landscape')]:
 for key,(title,headline,intro,art,stats,links) in pages.items():
  pref=lambda k:f'{alt}-{k}.html'
  nav=''.join(f'<a href="{pref("uk") if t=="Explore" else "#tool-"+t.lower()}">{t}</a>' for t in ['Explore','News','Signals','Opportunities','Pipeline'])
  cr=f'<a href="{pref("uk")}">UK</a>'+(f'<span>/</span><a href="{pref("banking" if key=="lloyds" else "technology")}">{"Banking" if key=="lloyds" else "Technology"}</a>' if key in ['lloyds','nvidia'] else '')
  lens=f'<div class="lenses"><a href="{pref("uk")}" '+('aria-current="page"' if key=='uk' else '')+f'>Economy</a><a href="{pref("government")}" '+('aria-current="page"' if key=='government' else '')+'>Government</a></div>' if key in ['uk','government'] else ''
  chips=''.join(f'<a href="{pref(k) if k in pages else "#"+k}">{e(t)} <span aria-hidden="true">→</span><small>{e(s)}</small></a>' for k,t,s in links)
  metrics=''.join(f'<div class="stat"><strong>{v}</strong><small>{s}</small></div>' for v,s in stats)
  groups= [('Enterprises', [('Lloyds Banking Group','lloyds'),('Santander UK','#questions'),('NatWest','#questions')]),('Suppliers & infrastructure',[('Supplier relationships · inspect scope','#ecosystem'),('Payment & technology infrastructure','#ecosystem')]),('Regulators & public institutions',[('Bank of England · institutional context','#ecosystem'),('FCA · jurisdiction must be checked','#ecosystem')])] if key in ['banking','lloyds'] else [('Enterprise districts',[('NVIDIA','nvidia'),('Cloud & data centres','#landscape'),('Software & connectivity','#landscape')]),('Suppliers & customers',[('Component / platform roles','#ecosystem'),('Customer segments · not named demand','#ecosystem')]),('Public institutions',[('Government · proposed lens','government'),('Regulatory remit · verify per activity','#ecosystem')])]
  if key=='uk':
   groups=[('Industry districts',[('Banking','banking'),('Technology','technology')]),('Connected economy',[('Production & infrastructure','#ecosystem'),('Services & everyday economy','#ecosystem')]),('Public institutions',[('Government lens','government'),('Public services','#services')])]
  if key=='government':
   groups=[('Public services',[('Departments · design grouping','#services'),('Delivery bodies · design grouping','#services')]),('Accountable spending',[('Procurement context','#procurement'),('Programmes · no live claim','#procurement')]),('Connected institutions',[('Regulatory roles','#ecosystem'),('Industry context','uk')])]
  gh=''.join('<section><h3>'+label+'</h3>'+''.join(f'<a href="{pref(dest) if dest in pages else dest}">{text} →</a>' for text,dest in rows)+'</section>' for label,rows in groups)
  skyline='<svg class="skyline" viewBox="0 0 1080 310" role="img" aria-labelledby="sky-title"><title id="sky-title">Grouped landscape concept; equal building heights are not financial scale. Equivalent links follow.</title>'
  for i,(group,rows) in enumerate(groups):
   skyline+=f'<text x="{i*360+20}" y="30" fill="currentColor" font-size="15">{e(group)}</text>'
   for j,(text,dest) in enumerate(rows[:2]):
    x=i*360+20+j*165; href=pref(dest) if dest in pages else dest
    skyline+=f'<a href="{href}" aria-label="{e(text)}"><rect x="{x}" y="85" width="145" height="155" rx="3" fill="#cbd9c7" stroke="#557367"/>'
    skyline+=''.join(f'<rect x="{x+15+c*30}" y="{105+r*30}" width="14" height="14" fill="#718e7c"/>' for r in range(3) for c in range(4))
    skyline+=f'<text x="{x+10}" y="275" fill="currentColor" font-size="12">{e(text[:22])}</text></a>'
  skyline+='</svg>'
  sources=''.join(f'<li><a href="{s["url"]}">{e(s["title"])}</a> · published {s["publication_date"] or "date not recorded"}; reviewed {s["reviewed_at"]}.</li>' for s in basis['sources'][:2])
  tools=''.join(f'<details id="tool-{t.lower()}" class="tool"><summary>{t} · design destination</summary><p>{desc}</p><p>This static study does not open private records, fetch news or create an opportunity.</p></details>' for t,desc in [('News','Weekly context-aware briefing proposed in #606. No articles or syndication rights are invented.'),('Signals','Existing dated change intelligence would retain country, source and identity restrictions. Forces of Change replaces ordinary PESTLE wording.'),('Opportunities','Existing authorised seller development and Offers remain authoritative. No automated qualification.'),('Pipeline','Existing authorised Pipeline service, approval and human hand-off remain unchanged.')])
  html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · {name} · FLORA VA-1 design</title><link rel="stylesheet" href="atlas.css"><body class="{alt}"><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html">FLORA</a><nav aria-label="Product">{nav}</nav><div class="identity"><span class="avatar" aria-hidden="true">SS</span><span>Strategic Sales<br>Design persona</span></div></header><main id="main" tabindex="-1"><section class="hero"><img class="art" src="assets/{art}" alt="" width="1536" height="1024"><div class="content"><div class="crumb" aria-label="Location">{cr}</div><p class="eyebrow">{title}</p><h1>{headline}</h1><p class="intro">{intro}</p>{lens}<div class="stats" aria-label="Economic context">{metrics}</div><div class="scene-links" aria-label="Explore this landscape">{chips}</div><div class="explore"><p>Follow the context. Find the next useful question.</p><a href="#landscape">Explore deeper ↓</a></div><p class="caption">Illustrated context · financial basis and sources in Explore deeper.</p></div></section><section class="depth"><h2 id="landscape">The connected landscape</h2><p>Grouped actors, with an equivalent text journey. Categories do not assert a company-to-company relationship.</p>{skyline}<div class="groups">{gh}</div><details><summary>Understand more</summary><details id="ecosystem"><summary>Connected ecosystem · direction and knownness</summary><p>Proposed edge grammar: supplier → enterprise (supplies an evidenced service); regulator → regulated activity (oversees within remit); enterprise → customer segment (serves). No named supplier/customer edge is asserted in this study. Unknown scope is shown as unknown; directional evidence and dates are required before activation.</p><p>Buildings group roles; heights do not compare revenue, GVA or influence.</p></details><details id="operating"><summary>Inside the enterprise</summary><p>Conceptual operating groups: customer outcomes → business capabilities → enabling operations. This is not a factual organisation chart. Existing enterprise evidence and models would supply verified detail.</p></details><details id="questions"><summary>Commercial questions</summary><p>What material customer problem remains unresolved? Who owns the decision? What evidence would disconfirm the need? Public strategy does not establish demand, access or available external scope. Early influence modelling is separately scoped in #604.</p></details><details id="services"><summary>Public-service landscape · proposed</summary><p>Departments, public services and delivery bodies are navigation concepts within the same UK context. Government includes non-market output; taxes are not turnover.</p></details><details id="procurement"><summary>Procurement context</summary><p>No active tender, funding or external scope is established by this mock-up. Future records need buyer, notice, dates, scope and source.</p></details><details><summary>Forces of Change</summary><p>Political, Economic, Social, Technological, Legal and Environmental perspectives reuse the existing PESTLE methodology and dated UK intelligence. This study does not add a new signal.</p></details><details><summary>Understand these figures</summary><p>UK GVA £2,623bn, 2024, GBP, current basic prices. Shares use whole SIC 2007 sections: K 8.1%, J 6.6%, O 5.1%; Banking and Technology are narrower research boundaries. UK real GDP +0.7% is a different measure and period, not sector growth. Frozen repository references have not been independently re-verified in this sprint.</p><p>Rounded section weights: computed sum {sum(r['weight_per_thousand'] for r in basis['districts'])}; metadata {basis['published_section_weight_sum']}; source note says 1,001. Reconcile in #607; never silently normalise or add section shares to enterprise revenue. Blank growth is deliberate. No estimates are invented; any future estimate needs EST, range, method and dated inputs.</p><p>NVIDIA reference: existing Commercial-Views.json / NV-FY26, global group FY2026 ended 25 January 2026, USD $215.938bn rounded to $215.94bn. Frozen reviewed presentation claim; not canonical acceptance or current verification. No UK revenue share inferred.</p><ul>{sources}</ul></details>{tools}</details></section></main><footer><span>VA-1 · {name} · design study only</span><a href="index.html">Compare three directions →</a></footer></body></html>'''
  (D/pref(key)).write_text(html)
index='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FLORA Visual Atlas · three directions</title><link rel="stylesheet" href="atlas.css"><body><main class="depth"><p class="eyebrow">FLORA / Visual Atlas VA-1 / Owner design review</p><h1>One world.<br>Three ways to explore.</h1><p>Static design studies. No product functionality, private records or live metrics.</p><div class="groups">'
for a,n,desc in [('a','Continuous Panorama','Warm, expansive and familiar. Recommended.'),('b','Spatial Atlas','Immersive forest-toned world; strongest separation of layers.'),('c','Editorial Landscape','Quiet typography and stable reading rail; stronger content hierarchy.')]:
 index+=f'<section><a href="{a}-uk.html"><img src="previews/desktop-{a}-uk.jpg" alt="{n} UK composition preview" style="width:100%;height:280px;object-fit:cover;object-position:top"></a><h2>{n}</h2><p>{desc}</p>'+''.join(f'<a href="{a}-{k}.html">{pages[k][0]} →</a>' for k in pages)+'</section>'
index+='</div><p>Choose a direction first. Metric reconciliation, Newsroom and live ecosystem implementation remain #607, #606 and #608 respectively.</p></main></body></html>'
(D/'index.html').write_text(index)
manifest={str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [R/'cios/applications/flora/visual_v2_assets/uk-economy.webp',R/'cios/applications/flora/research_intelligence/technology_experience_assets/uk-technology.webp']}
(D/'Artwork-Provenance.json').write_text(json.dumps({'reuse':'Existing approved FLORA conceptual artwork, byte-preserved; no external photography, logos or new rights claim','source_commit':'0cb07c2e78ccb16240c799b31cd62736e2135529','files':manifest},indent=2)+'\n')
